execute immediate $$
-- ============================================================================
-- scripts/reconcile_PACING_DEV1.sql  (build 17, D-51)
-- Read-only. Never deployed. Database = v_db.
-- Per lane, one statement: for every source table, METRIC_NAME and SNAPSHOT_DATE,
-- XFRM_<LANE>_PACING rows / non-null count / sum of the metric column against
-- SEM_AI_PACING rows / non-null count / sum of VALUE (tolerance 0.005). Equal
-- rows per cell over all metrics is the identity XFRM rows x k = SEM rows.
-- A cell on one side only fails (a new source table or a newly populated column).
-- Then COVERAGE (INFORMATION_SCHEMA, read live): every process lane, meaning a
-- lane with SPROC_XFRM_<LANE>_MAIN in the same database, whose XFRM_<LANE>_PACING
-- has rows must have rows in SEM_AI_PACING; a new process lane's pacing fails
-- here until it has a lane block. Any other XFRM_..._PACING table is listed as
-- 'not a process lane, not checked', with no status, and is not counted.
-- Last row: TOTAL / FAILURES across all statements. Zero is required.
-- ============================================================================
declare
    v_db   varchar default 'DEV1';
    v_sql  varchar;
    v_ids  array default array_construct();
    v_fin  varchar default '';
    res    resultset;
begin
    -- ------------------------------------------------------------------------
    -- ALTERRA
    -- ------------------------------------------------------------------------
    v_sql := replace('with s as (select source_table st, metric_name mn, snapshot_date sd, count(*) n, count(value) nn, sum(value) s from __DB__.SEMANTIC.SEM_AI_PACING where source_lane = ''ALTERRA'' group by 1, 2, 3)
, x as (select ''CLN.BOX_INVESTMENT_DATA.CLN_ALTERRA_PACE_GROUP_MONTHLY'' st, ''TODAY_ROOMS_COMMIT'' mn, snapshot_date sd, count(*) n, count(TODAY_ROOMS_COMMIT) nn, sum(TODAY_ROOMS_COMMIT::float) s from __DB__.TRANSFORMATION.XFRM_ALTERRA_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_ALTERRA_PACE_GROUP_MONTHLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_ALTERRA_PACE_GROUP_MONTHLY'' st, ''TODAY_ROOM_REVENUE_OTB'' mn, snapshot_date sd, count(*) n, count(TODAY_ROOM_REVENUE_OTB) nn, sum(TODAY_ROOM_REVENUE_OTB::float) s from __DB__.TRANSFORMATION.XFRM_ALTERRA_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_ALTERRA_PACE_GROUP_MONTHLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_ALTERRA_PACE_GROUP_MONTHLY'' st, ''STLY_DOW_ROOMS_COMMIT'' mn, snapshot_date sd, count(*) n, count(STLY_DOW_ROOMS_COMMIT) nn, sum(STLY_DOW_ROOMS_COMMIT::float) s from __DB__.TRANSFORMATION.XFRM_ALTERRA_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_ALTERRA_PACE_GROUP_MONTHLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_ALTERRA_PACE_GROUP_MONTHLY'' st, ''STLY_DOW_ROOM_REVENUE_OTB'' mn, snapshot_date sd, count(*) n, count(STLY_DOW_ROOM_REVENUE_OTB) nn, sum(STLY_DOW_ROOM_REVENUE_OTB::float) s from __DB__.TRANSFORMATION.XFRM_ALTERRA_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_ALTERRA_PACE_GROUP_MONTHLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_ALTERRA_PACE_GROUP_MONTHLY'' st, ''ST2Y_DOW_ROOMS_COMMIT'' mn, snapshot_date sd, count(*) n, count(ST2Y_DOW_ROOMS_COMMIT) nn, sum(ST2Y_DOW_ROOMS_COMMIT::float) s from __DB__.TRANSFORMATION.XFRM_ALTERRA_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_ALTERRA_PACE_GROUP_MONTHLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_ALTERRA_PACE_GROUP_MONTHLY'' st, ''ST2Y_DOW_ROOM_REVENUE_OTB'' mn, snapshot_date sd, count(*) n, count(ST2Y_DOW_ROOM_REVENUE_OTB) nn, sum(ST2Y_DOW_ROOM_REVENUE_OTB::float) s from __DB__.TRANSFORMATION.XFRM_ALTERRA_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_ALTERRA_PACE_GROUP_MONTHLY'' group by sd)
select ''ALTERRA'' lane, coalesce(s.st, x.st) source_table, coalesce(s.mn, x.mn) metric, coalesce(s.sd, x.sd)::varchar snapshot
     , x.n xfrm_rows, s.n sem_rows, x.nn xfrm_non_null, s.nn sem_non_null, x.s xfrm_sum, s.s sem_sum
     , iff(x.n is distinct from s.n or x.nn is distinct from s.nn or (x.s is null) <> (s.s is null) or abs(coalesce(x.s, 0) - coalesce(s.s, 0)) > 0.005, ''FAIL'', ''PASS'') status
from s full join x on s.st = x.st and s.mn = x.mn and s.sd = x.sd', '__DB__', :v_db);
    res := (execute immediate :v_sql);
    v_ids := array_append(v_ids, sqlid);
    -- ------------------------------------------------------------------------
    -- BEAUMIER
    -- ------------------------------------------------------------------------
    v_sql := replace('with s as (select source_table st, metric_name mn, snapshot_date sd, count(*) n, count(value) nn, sum(value) s from __DB__.SEMANTIC.SEM_AI_PACING where source_lane = ''BEAUMIER'' group by 1, 2, 3)
, x as (select ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' st, ''OCCUPANCY'' mn, file_date::date sd, count(*) n, count(OCCUPANCY) nn, sum(OCCUPANCY::float) s from __DB__.TRANSFORMATION.XFRM_BEAUMIER_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' st, ''ROOMS_REVENUE'' mn, file_date::date sd, count(*) n, count(ROOMS_REVENUE) nn, sum(ROOMS_REVENUE::float) s from __DB__.TRANSFORMATION.XFRM_BEAUMIER_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' st, ''OCCUPANCY_N_1'' mn, file_date::date sd, count(*) n, count(OCCUPANCY_N_1) nn, sum(OCCUPANCY_N_1::float) s from __DB__.TRANSFORMATION.XFRM_BEAUMIER_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' st, ''ROOMS_REVENUE_N_1'' mn, file_date::date sd, count(*) n, count(ROOMS_REVENUE_N_1) nn, sum(ROOMS_REVENUE_N_1::float) s from __DB__.TRANSFORMATION.XFRM_BEAUMIER_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' st, ''OCCUPANCY_N_2'' mn, file_date::date sd, count(*) n, count(OCCUPANCY_N_2) nn, sum(OCCUPANCY_N_2::float) s from __DB__.TRANSFORMATION.XFRM_BEAUMIER_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' st, ''ROOMS_REVENUE_N_2'' mn, file_date::date sd, count(*) n, count(ROOMS_REVENUE_N_2) nn, sum(ROOMS_REVENUE_N_2::float) s from __DB__.TRANSFORMATION.XFRM_BEAUMIER_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' st, ''OCCUPANCY_N_3'' mn, file_date::date sd, count(*) n, count(OCCUPANCY_N_3) nn, sum(OCCUPANCY_N_3::float) s from __DB__.TRANSFORMATION.XFRM_BEAUMIER_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' st, ''ROOMS_REVENUE_N_3'' mn, file_date::date sd, count(*) n, count(ROOMS_REVENUE_N_3) nn, sum(ROOMS_REVENUE_N_3::float) s from __DB__.TRANSFORMATION.XFRM_BEAUMIER_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' st, ''OCCUPANCY_N_4'' mn, file_date::date sd, count(*) n, count(OCCUPANCY_N_4) nn, sum(OCCUPANCY_N_4::float) s from __DB__.TRANSFORMATION.XFRM_BEAUMIER_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' st, ''ROOMS_REVENUE_N_4'' mn, file_date::date sd, count(*) n, count(ROOMS_REVENUE_N_4) nn, sum(ROOMS_REVENUE_N_4::float) s from __DB__.TRANSFORMATION.XFRM_BEAUMIER_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' st, ''OCCUPANCY_N_5'' mn, file_date::date sd, count(*) n, count(OCCUPANCY_N_5) nn, sum(OCCUPANCY_N_5::float) s from __DB__.TRANSFORMATION.XFRM_BEAUMIER_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' st, ''ROOMS_REVENUE_N_5'' mn, file_date::date sd, count(*) n, count(ROOMS_REVENUE_N_5) nn, sum(ROOMS_REVENUE_N_5::float) s from __DB__.TRANSFORMATION.XFRM_BEAUMIER_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_BEAUMIER_PACE_CANCELLATIONS_MONTHLY'' group by sd)
select ''BEAUMIER'' lane, coalesce(s.st, x.st) source_table, coalesce(s.mn, x.mn) metric, coalesce(s.sd, x.sd)::varchar snapshot
     , x.n xfrm_rows, s.n sem_rows, x.nn xfrm_non_null, s.nn sem_non_null, x.s xfrm_sum, s.s sem_sum
     , iff(x.n is distinct from s.n or x.nn is distinct from s.nn or (x.s is null) <> (s.s is null) or abs(coalesce(x.s, 0) - coalesce(s.s, 0)) > 0.005, ''FAIL'', ''PASS'') status
from s full join x on s.st = x.st and s.mn = x.mn and s.sd = x.sd', '__DB__', :v_db);
    res := (execute immediate :v_sql);
    v_ids := array_append(v_ids, sqlid);
    -- ------------------------------------------------------------------------
    -- KSL_SELECT_SERVICE
    -- ------------------------------------------------------------------------
    v_sql := replace('with s as (select source_table st, metric_name mn, snapshot_date sd, count(*) n, count(value) nn, sum(value) s from __DB__.SEMANTIC.SEM_AI_PACING where source_lane = ''KSL_SELECT_SERVICE'' group by 1, 2, 3)
, x as (select ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_EVENTS'' st, ''QTY'' mn, as_of_date sd, count(*) n, count(QTY) nn, sum(QTY::float) s from __DB__.TRANSFORMATION.XFRM_KSL_SELECT_SERVICE_PACING where source_table = ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_EVENTS'' group by sd union all select ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_EVENTS'' st, ''AMT_FOOD'' mn, as_of_date sd, count(*) n, count(AMT_FOOD) nn, sum(AMT_FOOD::float) s from __DB__.TRANSFORMATION.XFRM_KSL_SELECT_SERVICE_PACING where source_table = ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_EVENTS'' group by sd union all select ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_EVENTS'' st, ''AMT_BEV'' mn, as_of_date sd, count(*) n, count(AMT_BEV) nn, sum(AMT_BEV::float) s from __DB__.TRANSFORMATION.XFRM_KSL_SELECT_SERVICE_PACING where source_table = ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_EVENTS'' group by sd union all select ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_EVENTS'' st, ''AMT_RENT'' mn, as_of_date sd, count(*) n, count(AMT_RENT) nn, sum(AMT_RENT::float) s from __DB__.TRANSFORMATION.XFRM_KSL_SELECT_SERVICE_PACING where source_table = ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_EVENTS'' group by sd union all select ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_EVENTS'' st, ''AMT_RSRC'' mn, as_of_date sd, count(*) n, count(AMT_RSRC) nn, sum(AMT_RSRC::float) s from __DB__.TRANSFORMATION.XFRM_KSL_SELECT_SERVICE_PACING where source_table = ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_EVENTS'' group by sd union all select ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_EVENTS'' st, ''AMT_MISC'' mn, as_of_date sd, count(*) n, count(AMT_MISC) nn, sum(AMT_MISC::float) s from __DB__.TRANSFORMATION.XFRM_KSL_SELECT_SERVICE_PACING where source_table = ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_EVENTS'' group by sd union all select ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_EVENTS'' st, ''AMT_TOTAL'' mn, as_of_date sd, count(*) n, count(AMT_TOTAL) nn, sum(AMT_TOTAL::float) s from __DB__.TRANSFORMATION.XFRM_KSL_SELECT_SERVICE_PACING where source_table = ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_EVENTS'' group by sd union all select ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_ROOMS'' st, ''QTY'' mn, as_of_date sd, count(*) n, count(QTY) nn, sum(QTY::float) s from __DB__.TRANSFORMATION.XFRM_KSL_SELECT_SERVICE_PACING where source_table = ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_ROOMS'' group by sd union all select ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_ROOMS'' st, ''AMT'' mn, as_of_date sd, count(*) n, count(AMT) nn, sum(AMT::float) s from __DB__.TRANSFORMATION.XFRM_KSL_SELECT_SERVICE_PACING where source_table = ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_ROOMS'' group by sd union all select ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_ROOMS'' st, ''AVG_RATE'' mn, as_of_date sd, count(*) n, count(AVG_RATE) nn, sum(AVG_RATE::float) s from __DB__.TRANSFORMATION.XFRM_KSL_SELECT_SERVICE_PACING where source_table = ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_ROOMS'' group by sd union all select ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_TRANSIENT'' st, ''QTY'' mn, as_of_date sd, count(*) n, count(QTY) nn, sum(QTY::float) s from __DB__.TRANSFORMATION.XFRM_KSL_SELECT_SERVICE_PACING where source_table = ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_TRANSIENT'' group by sd union all select ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_TRANSIENT'' st, ''AMT'' mn, as_of_date sd, count(*) n, count(AMT) nn, sum(AMT::float) s from __DB__.TRANSFORMATION.XFRM_KSL_SELECT_SERVICE_PACING where source_table = ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_TRANSIENT'' group by sd union all select ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_TRANSIENT'' st, ''AVG_RATE'' mn, as_of_date sd, count(*) n, count(AVG_RATE) nn, sum(AVG_RATE::float) s from __DB__.TRANSFORMATION.XFRM_KSL_SELECT_SERVICE_PACING where source_table = ''CLN.CLEAN.CUR_PROFITSWORD_KSL_SALES_PACE_TRANSIENT'' group by sd)
select ''KSL_SELECT_SERVICE'' lane, coalesce(s.st, x.st) source_table, coalesce(s.mn, x.mn) metric, coalesce(s.sd, x.sd)::varchar snapshot
     , x.n xfrm_rows, s.n sem_rows, x.nn xfrm_non_null, s.nn sem_non_null, x.s xfrm_sum, s.s sem_sum
     , iff(x.n is distinct from s.n or x.nn is distinct from s.nn or (x.s is null) <> (s.s is null) or abs(coalesce(x.s, 0) - coalesce(s.s, 0)) > 0.005, ''FAIL'', ''PASS'') status
from s full join x on s.st = x.st and s.mn = x.mn and s.sd = x.sd', '__DB__', :v_db);
    res := (execute immediate :v_sql);
    v_ids := array_append(v_ids, sqlid);
    -- ------------------------------------------------------------------------
    -- NEWBURY
    -- ------------------------------------------------------------------------
    v_sql := replace('with s as (select source_table st, metric_name mn, snapshot_date sd, count(*) n, count(value) nn, sum(value) s from __DB__.SEMANTIC.SEM_AI_PACING where source_lane = ''NEWBURY'' group by 1, 2, 3)
, x as (select ''CLN.BOX_INVESTMENT_DATA.CLN_NEWBURY_BOSTON_OPS_STATS_DAILY_FORECAST'' st, ''ROOMS'' mn, coalesce(report_date, file_report_date) sd, count(*) n, count(ROOMS) nn, sum(ROOMS::float) s from __DB__.TRANSFORMATION.XFRM_NEWBURY_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_NEWBURY_BOSTON_OPS_STATS_DAILY_FORECAST'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_NEWBURY_BOSTON_OPS_STATS_DAILY_FORECAST'' st, ''REVENUE'' mn, coalesce(report_date, file_report_date) sd, count(*) n, count(REVENUE) nn, sum(REVENUE::float) s from __DB__.TRANSFORMATION.XFRM_NEWBURY_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_NEWBURY_BOSTON_OPS_STATS_DAILY_FORECAST'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_NEWBURY_BOSTON_PACE_OTB_DAILY_PICKUP_1DAY'' st, ''ROOMS'' mn, coalesce(report_date, file_report_date) sd, count(*) n, count(ROOMS) nn, sum(ROOMS::float) s from __DB__.TRANSFORMATION.XFRM_NEWBURY_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_NEWBURY_BOSTON_PACE_OTB_DAILY_PICKUP_1DAY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_NEWBURY_BOSTON_PACE_OTB_DAILY_PICKUP_1DAY'' st, ''REVENUE'' mn, coalesce(report_date, file_report_date) sd, count(*) n, count(REVENUE) nn, sum(REVENUE::float) s from __DB__.TRANSFORMATION.XFRM_NEWBURY_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_NEWBURY_BOSTON_PACE_OTB_DAILY_PICKUP_1DAY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_NEWBURY_BOSTON_PACE_OTB_DAILY_PICKUP_1DAY'' st, ''AVAILABLE_ROOMS'' mn, coalesce(report_date, file_report_date) sd, count(*) n, count(AVAILABLE_ROOMS) nn, sum(AVAILABLE_ROOMS::float) s from __DB__.TRANSFORMATION.XFRM_NEWBURY_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_NEWBURY_BOSTON_PACE_OTB_DAILY_PICKUP_1DAY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_NEWBURY_BOSTON_PACE_OTB_DAILY_PICKUP_3DAY'' st, ''ROOMS'' mn, coalesce(report_date, file_report_date) sd, count(*) n, count(ROOMS) nn, sum(ROOMS::float) s from __DB__.TRANSFORMATION.XFRM_NEWBURY_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_NEWBURY_BOSTON_PACE_OTB_DAILY_PICKUP_3DAY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_NEWBURY_BOSTON_PACE_OTB_DAILY_PICKUP_3DAY'' st, ''REVENUE'' mn, coalesce(report_date, file_report_date) sd, count(*) n, count(REVENUE) nn, sum(REVENUE::float) s from __DB__.TRANSFORMATION.XFRM_NEWBURY_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_NEWBURY_BOSTON_PACE_OTB_DAILY_PICKUP_3DAY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_NEWBURY_BOSTON_PACE_OTB_DAILY_PICKUP_3DAY'' st, ''AVAILABLE_ROOMS'' mn, coalesce(report_date, file_report_date) sd, count(*) n, count(AVAILABLE_ROOMS) nn, sum(AVAILABLE_ROOMS::float) s from __DB__.TRANSFORMATION.XFRM_NEWBURY_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_NEWBURY_BOSTON_PACE_OTB_DAILY_PICKUP_3DAY'' group by sd)
select ''NEWBURY'' lane, coalesce(s.st, x.st) source_table, coalesce(s.mn, x.mn) metric, coalesce(s.sd, x.sd)::varchar snapshot
     , x.n xfrm_rows, s.n sem_rows, x.nn xfrm_non_null, s.nn sem_non_null, x.s xfrm_sum, s.s sem_sum
     , iff(x.n is distinct from s.n or x.nn is distinct from s.nn or (x.s is null) <> (s.s is null) or abs(coalesce(x.s, 0) - coalesce(s.s, 0)) > 0.005, ''FAIL'', ''PASS'') status
from s full join x on s.st = x.st and s.mn = x.mn and s.sd = x.sd', '__DB__', :v_db);
    res := (execute immediate :v_sql);
    v_ids := array_append(v_ids, sqlid);
    -- ------------------------------------------------------------------------
    -- OUTRIGGER
