IT_PICKUP_7_DAY::float) s from __DB__.TRANSFORMATION.XFRM_UNDER_CANVAS_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_UNDER_CANVAS_PACE_OTB_WEEKLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_UNDER_CANVAS_PACE_OTB_WEEKLY'' st, ''ST2Y_DATE_ROOMS_COMMIT'' mn, snapshot_date sd, count(*) n, count(ST2Y_DATE_ROOMS_COMMIT) nn, sum(ST2Y_DATE_ROOMS_COMMIT::float) s from __DB__.TRANSFORMATION.XFRM_UNDER_CANVAS_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_UNDER_CANVAS_PACE_OTB_WEEKLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_UNDER_CANVAS_PACE_OTB_WEEKLY'' st, ''ST2Y_DATE_ROOM_REVENUE_COMMIT'' mn, snapshot_date sd, count(*) n, count(ST2Y_DATE_ROOM_REVENUE_COMMIT) nn, sum(ST2Y_DATE_ROOM_REVENUE_COMMIT::float) s from __DB__.TRANSFORMATION.XFRM_UNDER_CANVAS_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_UNDER_CANVAS_PACE_OTB_WEEKLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_UNDER_CANVAS_PACE_OTB_WEEKLY'' st, ''ST2Y_DATE_ROOMS_COMMIT_PICKUP_7_DAY'' mn, snapshot_date sd, count(*) n, count(ST2Y_DATE_ROOMS_COMMIT_PICKUP_7_DAY) nn, sum(ST2Y_DATE_ROOMS_COMMIT_PICKUP_7_DAY::float) s from __DB__.TRANSFORMATION.XFRM_UNDER_CANVAS_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_UNDER_CANVAS_PACE_OTB_WEEKLY'' group by sd union all select ''CLN.BOX_INVESTMENT_DATA.CLN_UNDER_CANVAS_PACE_OTB_WEEKLY'' st, ''ST2Y_DATE_ROOM_REVENUE_COMMIT_PICKUP_7_DAY'' mn, snapshot_date sd, count(*) n, count(ST2Y_DATE_ROOM_REVENUE_COMMIT_PICKUP_7_DAY) nn, sum(ST2Y_DATE_ROOM_REVENUE_COMMIT_PICKUP_7_DAY::float) s from __DB__.TRANSFORMATION.XFRM_UNDER_CANVAS_PACING where source_table = ''CLN.BOX_INVESTMENT_DATA.CLN_UNDER_CANVAS_PACE_OTB_WEEKLY'' group by sd)
select ''UNDER_CANVAS'' lane, coalesce(s.st, x.st) source_table, coalesce(s.mn, x.mn) metric, coalesce(s.sd, x.sd)::varchar snapshot
     , x.n xfrm_rows, s.n sem_rows, x.nn xfrm_non_null, s.nn sem_non_null, x.s xfrm_sum, s.s sem_sum
     , iff(x.n is distinct from s.n or x.nn is distinct from s.nn or (x.s is null) <> (s.s is null) or abs(coalesce(x.s, 0) - coalesce(s.s, 0)) > 0.005, ''FAIL'', ''PASS'') status
from s full join x on s.st = x.st and s.mn = x.mn and s.sd = x.sd', '__DB__', :v_db);
    res := (execute immediate :v_sql);
    v_ids := array_append(v_ids, sqlid);
    -- ------------------------------------------------------------------------
    -- COVERAGE: process lanes checked; other XFRM_..._PACING tables listed only (D-51)
    -- ------------------------------------------------------------------------
    v_sql := replace('select regexp_substr(t.table_name, ''^XFRM_(.*)_PACING$'', 1, 1, ''e'') lane, ''COVERAGE'' source_table
     , iff(m.procedure_name is null, ''not a process lane, not checked'', ''LANE_IN_SEM_AI_PACING'') metric, null snapshot
     , t.row_count xfrm_rows, iff(m.procedure_name is null, null, coalesce(p.n, 0)) sem_rows, null xfrm_non_null, null sem_non_null, null xfrm_sum, null sem_sum
     , case when m.procedure_name is null then null when coalesce(p.n, 0) = 0 then ''FAIL'' else ''PASS'' end status
from __DB__.INFORMATION_SCHEMA.TABLES t
left join (select distinct procedure_name from __DB__.INFORMATION_SCHEMA.PROCEDURES where procedure_schema = ''TRANSFORMATION'') m
       on m.procedure_name = ''SPROC_XFRM_'' || regexp_substr(t.table_name, ''^XFRM_(.*)_PACING$'', 1, 1, ''e'') || ''_MAIN''
left join (select source_lane, count(*) n from __DB__.SEMANTIC.SEM_AI_PACING group by 1) p
       on p.source_lane = regexp_substr(t.table_name, ''^XFRM_(.*)_PACING$'', 1, 1, ''e'')
where t.table_schema = ''TRANSFORMATION''
  and t.table_name like ''XFRM\\\\_%\\\\_PACING'' escape ''\\\\''
  and (t.row_count > 0 or m.procedure_name is null)', '__DB__', :v_db);
    res := (execute immediate :v_sql);
    v_ids := array_append(v_ids, sqlid);
    -- ------------------------------------------------------------------------
    -- union, then the single total
    -- ------------------------------------------------------------------------
    for i in 0 to array_size(:v_ids) - 1 do
        v_fin := v_fin || iff(i = 0, '', ' union all ') || 'select lane, source_table, metric, snapshot, xfrm_rows, sem_rows, xfrm_non_null, sem_non_null, xfrm_sum, sem_sum, status from table(result_scan(''' || v_ids[i]::varchar || '''))';
    end for;
    v_sql := 'with a as (' || v_fin || ') '
          || 'select lane, source_table, metric, snapshot, xfrm_rows, sem_rows, xfrm_non_null, sem_non_null, xfrm_sum, sem_sum, status from a '
          || 'union all '
          || 'select ''ALL'', ''TOTAL'', ''FAILURES'', null, count_if(status = ''FAIL''), null, null, null, null, null, iff(count_if(status = ''FAIL'') = 0, ''PASS'', ''FAIL'') from a '
          || 'order by source_table = ''TOTAL'', lane, source_table, metric, snapshot';
    res := (execute immediate :v_sql);
    return table(res);
end;
$$
